from calc1_core import *
x,a,h=s.symbols('x a h',real=True)
D=CalcDoc('1.1',list(range(17,22)),lambda n:17 if n<=5 else 18 if n<=23 else 19 if n<=38 else 20 if n<=72 else 21)
def add(n,st,steps,ans,check,parts=(),topic=('함수의 표현','Representing functions'),hint=('입력의 범위와 각 입력에 대응하는 출력부터 확인한다.','First identify the allowed inputs and the output assigned to each input.')):
 return D.add(n,topic,st,hint,steps,ans,check,parts)
add(1,('두 식 '+m(r'f(x)=x+\sqrt{2-x},\quad g(u)=u+\sqrt{2-u}')+'가 같은 함수인지 판단하라.','Decide whether '+m(r'f(x)=x+\sqrt{2-x},\quad g(u)=u+\sqrt{2-u}')+' represent the same function.'),[('변수 이름을 바꾸어도 입력과 출력의 대응은 변하지 않는다.','Renaming the input variable does not change the input-output rule.'),('두 식 모두 실수 입력이 2 이하일 때 정의된다.','Both expressions are defined for real inputs at most 2.')],('같다. 공통 정의역은 '+m(r'(-\infty,2]')+'.','Yes. Their common domain is '+m(r'(-\infty,2]')+'.'),('임의의 t≤2를 양쪽 식에 넣으면 같은 값 t+√(2−t)를 얻는다.','Every t≤2 produces the same value t+√(2−t) in both formulas.'))
add(2,('함수 '+m(r'f(x)=\frac{x^2-x}{x-1},\quad g(x)=x')+'의 동일성을 판단하라.','Determine whether '+m(r'f(x)=\frac{x^2-x}{x-1},\quad g(x)=x')+' are identical functions.'),[('분자를 인수분해하면 x(x−1)이므로 x≠1에서 f(x)=x이다.','Factoring the numerator gives x(x−1), so f(x)=x for x≠1.'),('약분은 원래 정의되지 않은 입력 x=1을 추가하지 않는다.','Cancellation does not add the originally excluded input x=1.')],('다르다: '+m(r'D_f=\mathbb R\setminus\{1\},\ D_g=\mathbb R')+'.','No: '+m(r'D_f=\mathbb R\setminus\{1\},\ D_g=\mathbb R')+'.'),('g(1)=1이지만 f(1)은 분모가 0이라 정의되지 않는다.','g(1)=1, whereas f(1) is undefined because its denominator is zero.'))
gleft=[(-4,3),(-3,2.8),(-2,2),(-1,0),(0,-2),(1,-1.4),(2,1)];gright=[(2,3),(2.5,2.85),(3,2.5),(3.5,1.9),(4,0)]
add(3,('주어진 g의 그래프에서 (a) g(−2),g(0),g(2),g(3), (b) g(x)=3의 해, (c) g(x)≤3의 해, (d) 정의역·치역, (e) 증가구간을 읽어라. 실선 점 (2,1)과 열린 점 (2,3)을 구분한다.','Read from the supplied graph of g: (a) its values at −2,0,2,3; (b) the solutions of g(x)=3; (c) the inputs with g(x)≤3; (d) domain and range; (e) intervals of increase. Distinguish the filled point (2,1) from the open point (2,3).'),[('x=2의 함수값은 열린 점의 높이가 아닌 닫힌 점의 높이 1이다. x=3은 격자에서 약 2.5으로 읽는다.','At x=2 the filled point gives 1; the open point is excluded. At x=3 the graph gives approximately 2.5.'),('가장 왼쪽·오른쪽 입력은 −4,4이고 최솟값은 −2, 최댓값은 3이다. 왼쪽 가지는 x=0에서 감소에서 증가로 바뀐다.','The extreme inputs are −4 and 4; the minimum and maximum outputs are −2 and 3. The left branch changes from decreasing to increasing at x=0.')],('(a) 2,−2,1,약2.5; (b) x=−4; (c) [−4,4]; (d) D=[−4,4], R=[−2,3]; (e) [0,2].','(a) 2,−2,1,approximately 2.5; (b) x=−4; (c) [−4,4]; (d) D=[−4,4], R=[−2,3]; (e) [0,2].'),('y=3과의 오른쪽 교점은 열린 점이므로 해에서 제외한다. 증가구간의 오른쪽 끝은 점프 이후 감소하는 가지를 포함하지 않는다. g(3)은 도해 추정값이다.','The right intersection with y=3 is open and is excluded. The increasing interval stops before the decreasing right branch. The value g(3) is a graphical estimate.'),list('abcde'))
D.fig(3,[panel('g: endpoints and branches',(-4.5,4.5,-2.5,3.5),[gleft,gright],[(-4,3),(2,1),(2,3,'open'),(4,0)],list(range(-4,5)),list(range(-2,4)))],('원본의 격자·점·증감을 보존한 자체 개략도. 중간 곡률은 근사한다.','Original schematic preserving the source grid readings, endpoints, and monotonicity; intermediate curvature is approximate.'))
f4=[(-4,-2),(-3,-1),(-2,1),(-1,2.5),(0,3),(1,2.75),(2,2),(3,.9),(4,-1)];g4=[(-4,2.5),(-3,2),(-2,1),(-1,.6),(0,.5),(1,.9),(2,2),(3,4)]
add(4,('두 그래프 f(빨강),g(파랑)에 대해 (a) f(−4),g(3), (b) f(−3)와 g(−3)의 대소, (c) 교점의 x, (d) f≤g인 구간, (e) f(x)=−1의 해, (f) g의 감소구간, (g,h) 각각 정의역·치역을 구하라.','For the red graph f and blue graph g, find (a) f(−4),g(3); (b) which is larger at −3; (c) intersection inputs; (d) where f≤g; (e) the solutions of f(x)=−1; (f) where g decreases; (g,h) their respective domains and ranges.'),[('높이를 비교하면 교점은 x=−2,2이다. 두 함수가 함께 정의되는 구간은 [−4,3]이다.','Comparing heights gives intersections at x=−2 and 2. The common domain is [−4,3].'),('f의 최저 높이는 −2, 최고는 3이다. g의 최저 높이는 약0.5이며 x=0에서 나타나고 최고는4이다.','The minimum and maximum heights of f are −2 and 3. The minimum height of g is approximately 0.5 at x=0, and its maximum is 4.')],('(a) −2,4; (b) g(−3)>f(−3); (c) −2,2; (d) [−4,−2]∪[2,3]; (e) −3,4; (f) [−4,0]; (g) Df=[−4,4], Rf=[−2,3]; (h) Dg=[−4,3], Rg≈[0.5,4].','(a) −2,4; (b) g(−3)>f(−3); (c) −2,2; (d) [−4,−2]∪[2,3]; (e) −3,4; (f) [−4,0]; (g) Df=[−4,4], Rf=[−2,3]; (h) Dg=[−4,3], Rg≈[0.5,4].'),('x=0에서 f>g, x=−3과3에서 f<g임을 확인하여 교점 사이와 밖의 부호를 대조했다. g 최솟값은 격자 판독 근삿값이다.','At x=0, f>g; at x=−3 and 3, f<g, confirming the signs between and outside the intersections. The minimum of g is a grid-reading estimate.'),list('abcdefgh'))
D.fig(4,[panel('f (red), g (blue)',(-4.5,4.5,-2.5,4.5),[{'points':f4,'color':'#dc2626'},{'points':g4,'color':'#1d4ed8'}],xticks=list(range(-4,5)),yticks=list(range(-2,5)))],('원본의 교점과 끝점, 극값을 보존한 자체 개략도.','Original schematic preserving source intersections, endpoints, and extrema.'))
add(5,('이 절의 Northridge 지진 기록(Figure 1, 인쇄8쪽)에서 USC의 수직 지면가속도 치역을 추정하라.','Estimate the range of vertical ground acceleration at USC from the Northridge earthquake trace in Figure 1 (printed page 8).'),[('시간축 전체에서 가장 아래쪽 진동과 가장 높은 양의 스파이크를 찾는다.','Locate the lowest oscillation and the highest positive spike over the full time interval.'),('50 cm/s² 간격 눈금으로 읽으면 아래끝은 약 −85, 위끝은 약130이다.','Using the 50 cm/s² tick spacing gives a lower endpoint near −85 and an upper endpoint near 130.')],d(r'\operatorname{range}(a)\approx[-85,130]\ \mathrm{cm/s^2}'),('원본 PDF45를 직접 대조했다. 얇은 파형의 극값 판독이므로 끝값 몇 cm/s² 정도의 차이는 가능하다.','Checked directly against PDF page 45. Thin trace extrema allow a few cm/s² of reading variation.'))
add(6,('일상적인 함수 세 가지를 직접 제시하고 각 정의역·치역을 설명하며 가능한 그래프를 그려라.','Give three everyday examples of functions, state their domains and ranges, and draw possible graphs.'),[('예1: 일정 속도 5 km/h로2시간 걷는 거리 d(t)=5t. D=[0,2], R=[0,10].','Example 1: distance walked at 5 km/h for 2 hours, d(t)=5t. D=[0,2], R=[0,10].'),('예2: 처음10 L인 통에 분당2 L씩5분 동안 물을 채우는 양 V(t)=10+2t. D=[0,5], R=[10,20].','Example 2: water in a tank starting at 10 L and filled at 2 L/min for 5 minutes, V(t)=10+2t. D=[0,5], R=[10,20].'),('예3: 개당2달러인 물건을 0~5개 살 때 비용 C(n)=2n. D={0,1,2,3,4,5}, R={0,2,4,6,8,10}; 점들을 선으로 잇지 않는다.','Example 3: buying 0 to 5 items at $2 each, C(n)=2n. D={0,1,2,3,4,5}, R={0,2,4,6,8,10}; the graph consists of isolated points.')],('위 세 가지는 가능한 예이며 답은 유일하지 않다.','These are three possible examples; answers are not unique.'),('각 입력에 출력 하나만 대응하며 거리와 물의 양은 연속 입력, 물건 수는 정수 입력임을 확인했다.','Each input has one output; distance and water use continuous inputs, whereas item count uses integer inputs.'))
D.fig(6,[panel('Walking distance (km)',(0,2,0,10),[[(0,0),(2,10)]],xlabel='hours'),panel('Water volume (L)',(0,5,0,20),[[(0,10),(5,20)]],xlabel='min'),panel('Cost ($)',(-.5,5.5,0,11),dots=[(i,2*i) for i in range(6)],xticks=list(range(6)),xlabel='items')])
relations=[(7,r'3x-5y=7',True,r'y=(3x-7)/5','일차식을 y에 대해 풀면 하나의 실수값을 얻는다.','Solving the linear equation for y gives one real value.','x=0이면 y=−7/5 하나뿐이다.','At x=0 the only output is −7/5.'),(8,r'3x^2-2y=5',True,r'y=(3x^2-5)/2','x²은 입력마다 유일하며 y의 계수가0이 아니다.','Each input determines x² uniquely and the coefficient of y is nonzero.','x=±1에서 모두 y=−1이지만 서로 다른 입력의 출력이 같아도 함수이다.','Both ±1 give −1; different inputs may share an output.'),(9,r'x^2+(y-3)^2=5',False,r'x=0\Longrightarrow y=3\pm\sqrt5','제곱근의 양·음 두 가지가 가능하다.','Both square-root signs are possible.','3+√5와3−√5를 원래 식에 넣으면 둘 다5가 된다.','Both 3+√5 and 3−√5 satisfy the original equation at x=0.'),(10,r'2xy+5y^2=4',False,r'x=0\Longrightarrow y=\pm2/\sqrt5','한 입력 x=0이 두 출력을 갖는다.','The single input x=0 has two outputs.','두 값 모두 5y²=4를 만족한다.','Both values satisfy 5y²=4.'),(11,r'(y+3)^3+1=2x',True,r'y=\sqrt[3]{2x-1}-3','실수 세제곱근은 모든 실수에서 유일하다.','The real cube root is unique for every real argument.','구한 식에3을 더해 세제곱하면2x−1이 복원된다.','Adding 3 and cubing restores 2x−1.'),(12,r'2x-|y|=0',False,r'x=1\Longrightarrow y=\pm2','절댓값은 서로 반대인 두 수에서 같은 값을 갖는다.','Opposite numbers have the same absolute value.','y=2와−2 모두 x=1에서2−|y|=0을 만족한다.','Both y=2 and −2 satisfy 2−|y|=0 at x=1.')]
for n,eq,yes,res,ko,en,ck,ce in relations:
 add(n,('관계 '+m(eq)+'가 y를 x의 함수로 정하는지 판단하라.','Determine whether '+m(eq)+' defines y as a function of x.'),[(ko,en),(d(res),d(res))],('함수이다.' if yes else '함수가 아니다.','It is a function.' if yes else 'It is not a function.'),(ck,ce))
for n,data,yes,ko,en in [(13,[(72,12),(60,8),(60,7),(63,9),(70,10)],False,'키60인 입력이 신발 크기8과7에 모두 대응한다.','Height 60 is paired with both shoe sizes 8 and 7.'),(14,[(2016,10900),(2017,11000),(2018,11200),(2019,11200),(2020,11300)],True,'각 연도에는 수업료가 하나만 있다. 서로 다른 연도의 수업료가 같아도 된다.','Each year has one tuition value. Different years may have the same tuition.')]:
 add(n,('순서쌍 '+str(data)+'에서 두 번째 값이 첫 번째 값의 함수인가?','Do the pairs '+str(data)+' define the second coordinate as a function of the first?'),[(ko,en)],('예.' if yes else '아니오.','Yes.' if yes else 'No.'),('첫 좌표별로 묶어 출력 수를 세어 확인했다.','Grouping by the first coordinate confirms the number of distinct outputs.'))
for n,desc,desce,ko,en,ans,anse,ck,ce in [(15,'옆으로 굽은 S자 곡선','a sideways S-shaped curve','수직선 x=0은 곡선을 세 번 지난다.','The vertical line x=0 meets the curve three times.','함수가 아니다.','Not a function.','같은 x에서 위·중간·아래의 서로 다른 높이가 나온다.','The same x gives distinct upper, middle, and lower heights.'),(16,'끝점(−2,1),(2,2), 최저점의 높이−1을 갖는 곡선','a curve with endpoints (−2,1),(2,2) and minimum height −1','수직선은 최대 한 번 만나며 양끝점도 포함된다.','Each vertical line meets at most once, and both endpoints are included.','함수이다. D=[−2,2], R=[−1,2].','A function. D=[−2,2], R=[−1,2].','최저점−1부터 오른쪽 끝 높이2까지 모든 중간 높이를 지난다.','Every height from the minimum −1 to the right endpoint height 2 occurs.'),(17,'닫힌(−3,−3)에서 열린(−2,−2)까지의 선분 및 닫힌(−2,−1)에서 x=2까지 이어지고 최고높이3을 갖는 곡선','a segment from filled (−3,−3) to open (−2,−2), plus a curve beginning at filled (−2,−1), ending at x=2, and reaching height 3','x=−2에서는 아래 열린 점을 제외하므로 출력이−1 하나이다.','At x=−2 the lower point is open, so the only output is −1.','함수이다. D=[−3,2], R=[−3,−2)∪[−1,3].','A function. D=[−3,2], R=[−3,−2)∪[−1,3].','치역에서−2는 제외되고−1은 포함된다. 위 곡선은 높이3에 도달한다.','The range excludes −2 and includes −1. The upper curve attains height 3.'),(18,'수평 선분들을 수직 선분으로 연결한 계단','a staircase whose horizontal pieces are joined by vertical segments','수직 연결선 하나에도 같은 입력의 출력이 여러 개 있다.','Each vertical connector gives several outputs for one input.','함수가 아니다.','Not a function.','x=1의 수직선분에서 y=0부터1까지가 함께 나타난다.','At x=1 the connector contains every y from 0 to 1.')]:
 add(n,('도해의 '+desc+'이 함수 그래프인지 판단하고 함수라면 정의역·치역을 구하라.','For '+desce+' in the diagram, decide whether it is a function graph and, if so, find its domain and range.'),[(ko,en)],(ans,anse),(ck,ce))
D.fig(15,[panel('Vertical-line test',(-3,3,-3,3),[[(y**3/3-y,y) for y in [i/100 for i in range(-220,221)]]],xticks=list(range(-3,4)),yticks=list(range(-3,4)))])
D.fig(16,[panel('Domain and range',(-3,3,-2,3),[[(-2,1),(-1.5,0),(-.4,-1),(0,-.9),(1,1),(2,2)]],[(-2,1),(2,2)],list(range(-3,4)),list(range(-2,4)))])
D.fig(17,[panel('Open and filled endpoints',(-3.5,2.5,-3.5,3.5),[[(-3,-3),(-2,-2)],[(-2,-1),(-1,.8),(0,2),(1.3,3),(2,2.65)]],[(-3,-3),(-2,-2,'open'),(-2,-1),(2,2.65)],list(range(-3,3)),list(range(-3,4)))])
D.fig(18,[panel('Staircase with vertical connectors',(-3,3,-3,3),[[q for k in range(-3,3) for q in [(k,k),(k+1,k),(k+1,k+1)]]],xticks=list(range(-3,4)),yticks=list(range(-3,4)))])
add(19,('1900~2000년 평균기온 그래프에서 (a)1950년 기온,(b)14.2°C인 연도,(c)최저·최고 연도,(d)치역을 추정하라.','Use the 1900–2000 temperature graph to estimate (a) the 1950 temperature, (b) the year at 14.2°C, (c) the years of minimum and maximum temperature, and (d) the range.'),[('1950년 수직선의 높이는14°C보다 약0.15°C 낮다. 14.2°C 수평선은 약1980년에 곡선을 만난다.','The height at 1950 is about 0.15°C below 14°C. The horizontal line at 14.2°C meets the curve near 1980.'),('가장 낮은 골은1910년 부근13.5°C이고 오른쪽 끝2000년이 약14.4°C로 가장 높다.','The lowest trough is near 1910 at about 13.5°C; the right endpoint at 2000 is highest at about 14.4°C.')],('(a) 약13.85°C; (b) 약1980년; (c) 약1910년·2000년; (d) 약[13.5,14.4]°C.','(a) About 13.85°C; (b) about 1980; (c) about 1910 and 2000; (d) approximately [13.5,14.4]°C.'),('원본의 세로 작은 눈금0.2°C와 가로1900,1950,2000을 사용했다. 수치는 도해 해상도에 따른 근삿값이다.','Read using the 0.2°C minor ticks and the 1900,1950,2000 horizontal labels. Values are estimates limited by the graph resolution.'),list('abcd'))
D.fig(19,[panel('Historical temperature: schematic reading',(1900,2000,13,14.6),[[(1900,13.75),(1910,13.52),(1920,13.65),(1935,13.86),(1942,14.02),(1950,13.85),(1960,13.92),(1970,13.94),(1980,14.2),(1990,14.23),(2000,14.4)]],xticks=[1900,1925,1950,1975,2000],yticks=[13,13.4,13.8,14.2,14.6],xlabel='year',ylabel='C')],('판독 지점을 보여 주는 자체 개략도이며 원시 기후 데이터가 아니다.','Original schematic of the reading points; not raw climate data.'))
add(20,('1500~2000년 소나무 나이테 폭 그래프에서 (a)폭의 치역,(b)온도 변화의 경향과19세기 중반 화산분출이 반영되는지 논하라.','From the 1500–2000 pine ring-width graph, estimate (a) the range and (b) the suggested temperature trend and whether mid-nineteenth-century eruptions are reflected.'),[('최저 폭은 거의0 mm, 최고 스파이크는 약1.6 mm이다.','The smallest widths are nearly 0 mm; the highest spike is about 1.6 mm.'),('따뜻할수록 나이테가 넓다는 주어진 관계에 따르면20세기 말의 넓은 나이테는 온난화를 시사한다.19세기 중반의 좁아진 부분은 냉각과 양립한다.','Under the stated association between warmth and wider rings, large late-twentieth-century widths suggest warming. Narrower rings around the mid-nineteenth century are compatible with cooling.')],('(a) 약[0,1.6] mm. (b) 장기적으로 최근 온난화가 보인다. 화산분출에 따른 냉각과 부합하는 감소는 있지만 이 그림만으로 원인을 확정할 수는 없다.','(a) Approximately [0,1.6] mm. (b) The recent part suggests warming. A decrease is consistent with eruption-related cooling, but this graph alone cannot establish its cause.'),('추정치이며0은 정확한 관측치라는 뜻이 아니다. 한 나무의 나이테 기록을 전지구 온도의 정확한 측정값으로 동일시하지 않았다.','The lower endpoint is an estimate, not a claim of an exactly zero measurement. One tree record is not treated as an exact global temperature measurement.'),list('ab'))
qual=[(21,'얼음과 찬물을 담은 컵을 실내에 두었다. 시간에 따른 물 온도를 설명하고 개략 그래프를 그려라.','Describe and sketch the temperature of cold water with ice left in a room.','남아 있는 얼음과 물이 거의 평형이면 약0°C에서 유지된다. 얼음이 다 녹은 뒤 실내 온도에 접근하며 상승한다.','While ice and water are near equilibrium the temperature stays near 0°C. After melting, it rises toward room temperature.','처음 물이0°C보다 높다면 짧은 냉각 단계가 먼저 올 수 있다.','An initial cooling phase is possible if the water starts above 0°C.'),(22,'냉동 파이를 오븐에서1시간 굽고 꺼내 식힌다. 온도 변화를 설명하고 그려라.','A frozen pie is baked for one hour and then removed to cool. Describe and sketch its temperature.','가열 중 온도가 상승하며 해동 중 상승이 더딜 수 있다.1시간 뒤 실내로 꺼내면 주변 온도에 접근하며 내려간다.','Temperature rises during baking, possibly slowly during thawing. After removal at one hour, it falls toward room temperature.','오븐에서 꺼내는 순간 온도는 점프하지 않고 상승·하강 경향이 바뀐다.','Removal changes the heating trend without an instantaneous temperature jump.'),(25,'보통 봄날의 실외 온도를 하루 시간의 함수로 개략적으로 그려라.','Sketch a possible outdoor temperature curve over a typical spring day.','새벽 무렵 최저, 오후에 최고이며 저녁과 밤에 다시 내려가는 곡선이 한 예이다.','One possible curve has a minimum near dawn, a maximum in the afternoon, and cooling through evening and night.','날씨에 따라 달라지는 예시이므로 주어진 자료의 예측값으로 해석하지 않는다.','This is an illustrative weather pattern rather than a prediction from data.'),(26,'연중 시점에 따른 낮의 길이의 개략 그래프를 그려라.','Sketch hours of daylight as a function of time of year.','북반구 중위도를 예로 들면12월 최저,6월 최고이며 봄·가을 무렵 약12시간을 지난다.','For a northern midlatitude example, daylight is shortest in December and longest in June, passing about 12 hours near the equinoxes.','남반구에서는 최대·최소 계절이 반대이며 위도에 따라 진폭이 달라진다.','The seasonal extrema reverse in the Southern Hemisphere, and amplitude depends on latitude.'),(27,'커피 가격에 따른 특정 상표의 판매량을 개략적으로 그려라.','Sketch a possible quantity sold of a coffee brand as a function of price.','다른 조건을 고정하면 가격이 높아질수록 수요가 줄어드는 비음수 곡선을 택할 수 있다.','Holding other factors fixed, a nonnegative decreasing demand curve is a possible model.','가격과 판매량을 모두 비음수로 두며 모형이 유일하지 않음을 명시한다.','Both price and quantity are nonnegative, and the model is not unique.'),(28,'잘 관리한 새 자동차의20년 동안 시장가치를 시간의 함수로 그려라.','Sketch the market value of a well-maintained new car over 20 years.','처음 감가가 빠르고 이후 더 천천히 떨어져 낮은 잔존가치에 접근하는 모형이 가능하다.','A possible model depreciates quickly at first and then more slowly toward a low residual value.','골동품 가치 상승 등 별도 가정을 하지 않은 보통 감가 모형이다.','This is an ordinary depreciation model without an additional collectible-value assumption.'),(29,'매주 수요일 오후에 잔디를 깎는 집의 잔디 높이를4주 동안 그려라.','Sketch grass height over four weeks when the lawn is mowed every Wednesday afternoon.','깎기 사이에는 증가하고 매주 깎는 시점에 낮은 높이로 급감하는 톱니 모양이다.','Height increases between mowings and drops to a lower height at each weekly mowing.','순간 깎기 모형에서는 점프가 있지만 같은 시각에 두 높이를 지정하지 않도록 한쪽 끝을 연다.','The instantaneous-mowing model has jumps, with one endpoint open so that each instant has one height.')]
for n,st,se,ko,en,ck,ce in qual:add(n,(st,se),[(ko,en)],(ko,en),(ck,ce))
